begin;
set local statement_timeout='30s';
do $$
declare a uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid(); fid uuid:=gen_random_uuid(); target_email text; other_email text; r jsonb; denied boolean;
begin
 target_email:=u::text||'@shop-removal-test.invalid';other_email:=v::text||'@shop-removal-test.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(a,a::text||'@shop-removal-test.invalid',now()),(u,target_email,now()),(v,other_email,now());
 insert into public.platform_admins(user_id) values(a);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 insert into public.stores(id,name,category,owner_email,pickup_enabled,image) values(sid,'Fixture shop removal','shop',target_email,true,'https://example.invalid/deleted-store-fixture.webp');
 insert into public.business_applications(id,owner_id,store_id,status) values(aid,u,sid,'approved');
 insert into public.daily_offers(user_id,store_id,title,details,address,ends_at,status) values(v,sid,'Fixture offer','Fixture content','Fixture address',now()+interval '1 day','approved');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 insert into public.orders(id,store_id,customer_id,customer_name,phone,address,area,delivery_fee,items,subtotal,total,status) values(oid,sid,v,'Fixture customer','+963900000001','Fixture address','Fixture area',0,'[]',100,100,'جديد');
 denied:=false;begin perform public.admin_handle_account_deletion(u,'delete_shop',sid,null,'HANDLE '||target_email,true);exception when others then denied:=SQLERRM='ADMIN_REQUIRED';end;
 if not denied then raise exception 'Non-admin removal allowed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 r:=public.admin_account_deletion_details(u);
 if not exists(select 1 from jsonb_array_elements(r->'orders') x where x->>'id'=oid::text) then raise exception 'Other customer shop order missing';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'delete_shop',sid,null,'HANDLE wrong',true);exception when others then denied:=SQLERRM='CONFIRMATION_REQUIRED';end;
 if not denied then raise exception 'Wrong identity accepted';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'delete_shop',sid,null,'HANDLE '||target_email,true);exception when others then denied:=SQLERRM='STORE_TRANSACTIONS_OPEN';end;
 if not denied then raise exception 'Open shop order discarded';end if;
 if not exists(select 1 from public.stores where id=sid and owner_email=target_email and deleted_at is null) or not exists(select 1 from public.daily_offers where store_id=sid) then raise exception 'Blocked removal changed data';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(v,'delete_shop',sid,null,'HANDLE '||other_email,true);exception when others then denied:=SQLERRM='RESOURCE_CHANGED';end;
 if not denied then raise exception 'Wrong owner shop removed';end if;
 r:=public.admin_handle_account_deletion(u,'cancel_order',oid,null,'HANDLE '||target_email,true);
 if r->>'handled'<>'true' or not exists(select 1 from public.orders where id=oid and status='ملغي' and total=100 and customer_id=v) then raise exception 'Shop order cancellation failed';end if;
 insert into storage.buckets(id,name) values(u::text,u::text);
 insert into storage.objects(id,bucket_id,name,owner_id,owner) values(fid,u::text,'deleted-store-fixture.webp',u::text,u);
 denied:=false;begin perform public.admin_account_deletion_file(u,fid,'HANDLE '||target_email,true);exception when others then denied:=SQLERRM='FILE_IN_USE';end;
 if not denied then raise exception 'Active shop photo deletable';end if;
 r:=public.admin_handle_account_deletion(u,'delete_shop',sid,null,'HANDLE '||target_email,true);
 if r->>'handled'<>'true' then raise exception 'Unconfirmed removal';end if;
 if not exists(select 1 from public.stores where id=sid and owner_email='' and deleted_at is not null and not active and not is_open and not online_ordering and not delivery_enabled) then raise exception 'Shop still public or owned';end if;
 if exists(select 1 from public.daily_offers where store_id=sid) then raise exception 'Public offers remain';end if;
 if not exists(select 1 from public.orders where id=oid and total=100 and customer_id=v) then raise exception 'Order record lost';end if;
 if not exists(select 1 from public.business_applications where id=aid and owner_id=u and store_id is null) then raise exception 'Application still blocks deletion';end if;
 r:=public.admin_account_deletion_file(u,fid,'HANDLE '||target_email,true);
 if r->>'name'<>'deleted-store-fixture.webp' then raise exception 'File cleanup unavailable';end if;
 r:=public.admin_handle_account_deletion(u,'transfer_file',fid,other_email,'HANDLE '||target_email,true);
 r:=public.admin_execute_account_deletion(u,'DELETE '||target_email,true,null);
 if r->>'deleted'<>'true' or exists(select 1 from auth.users where id=u) then raise exception 'Account remains blocked';end if;
 if not exists(select 1 from auth.users where id=v) or not exists(select 1 from public.account_deletion_actions where target_id=u and action='delete_shop' and resource_id=sid) then raise exception 'Isolation or audit failed';end if;
end;$$;
rollback;
select 'PASS: role/owner/confirmation checks, open shop order guard, cancellation, shop/offer removal, retained financial records, application unlink, file handling and final account deletion. All fixtures rolled back.' result;
